#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<vector<double>>chain={{1,2,3,2},{2,3,4,3},{1,3,2,2}};
int m=chain.size(),n=chain[0].size();vector<double>mean(m),within(m);double pooled=0,W=0,B=0;
for(int c=0;c<m;c++){for(double x:chain[c])mean[c]+=x/n;pooled+=mean[c]/m;for(double x:chain[c])within[c]+=pow(x-mean[c],2)/(n-1);W+=within[c]/m;}
for(double v:mean)B+=n*pow(v-pooled,2)/(m-1);
double varHat=(n-1.0)/n*W+B/n;
cout<<"split-independent Rhat approximation "<<sqrt(varHat/W)<<"\n";
return 0;
}

